import itertools

# We have 7 vertices: 0,1,2,3,4,5,6
# Fixed edges: (0,6), (1,5)
# Need a maximal triangle-free graph

vertices = list(range(7))
all_possible_edges = [(i,j) for i in range(7) for j in range(i+1,7)]

fixed_edges = [(0,6), (1,5)]

def has_triangle(edges_set):
    """Check if the graph has any triangle"""
    adj = {v: set() for v in range(7)}
    for u,v in edges_set:
        adj[u].add(v)
        adj[v].add(u)
    for u in range(7):
        for v in adj[u]:
            if v > u:
                for w in adj[v]:
                    if w > v and w in adj[u]:
                        return True
    return False

def is_maximal(edges_set):
    """Check if adding any non-edge creates a triangle"""
    if has_triangle(edges_set):
        return False
    for u,v in all_possible_edges:
        if (u,v) not in edges_set and (v,u) not in edges_set:
            new_edges = edges_set | {(u,v)}
            if not has_triangle(new_edges):
                return False
    return True

